solution.solution.py:
def initials(name):
    return "".join(word[0].upper() + "." for word in name.split())


def is_palindrome(text):
    letters = "".join(c.lower() for c in text if c.isalpha())
    return letters == letters[::-1]


def count_vowels(text):
    return sum(1 for c in text.lower() if c in "aeiou")

unitTests:
@test("initials")
def _():
    check_eq(initials("ada lovelace"), "A.L.")
    check_eq(initials("Grace Brewster Hopper"), "G.B.H.")
    check_eq(initials("  linus   torvalds "), "L.T.")
    check_eq(initials(""), "")

@test("palindromes")
def _():
    check(is_palindrome("Racecar"))
    check(is_palindrome("A man, a plan, a canal: Panama!"))
    check(not is_palindrome("Python"))
    check(is_palindrome(""))

@test("vowels")
def _():
    check_eq(count_vowels("Programming in Python"), 5)
    check_eq(count_vowels("AEIOU aeiou"), 10)
    check_eq(count_vowels("rhythm"), 0)

